// Offscreen audio engine: fetches per-chunk TTS from the local Lectern server
// and plays it gaplessly (dual <audio> swap + prefetch window, mirroring the
// web app's player). Stateless by design — the service worker owns the
// session and can rehydrate this document at any position after Chrome closes
// it (30 s without audio).
const API = 'http://127.0.0.1:3000';
const WINDOW_AHEAD = 3;
const MAX_CONCURRENT = 2;
const TIME_INTERVAL_MS = 250;

let s = null; // { chunks, provider, voice, rate, idx, wantPlay, entries, inFlight, active, standby, standbyIdx, timeTimer }

const send = (msg) => chrome.runtime.sendMessage({ target: 'sw', ...msg }).catch(() => {});

function makeAudio() {
  const el = new Audio();
  el.preservesPitch = true;
  el.addEventListener('ended', () => onEnded(el));
  return el;
}

function stop() {
  if (!s) return;
  clearInterval(s.timeTimer);
  s.active.pause();
  s.standby.pause();
  for (const [, e] of s.entries) {
    // the engine drops an abandoned request that is still waiting for a
    // synthesis slot, so a voice switch or a stop frees it at once
    e.abort.abort();
    if (e.blobUrl) URL.revokeObjectURL(e.blobUrl);
  }
  s = null;
}

function start({ chunks, startChunk = 0, offsetMs = 0, charStart = null, provider, voice, rate = 1, autoplay = true }) {
  stop();
  s = {
    chunks,
    provider,
    voice,
    rate,
    idx: Math.min(startChunk, chunks.length - 1),
    wantPlay: autoplay,
    entries: new Map(),
    inFlight: 0,
    active: makeAudio(),
    standby: makeAudio(),
    standbyIdx: -1,
    pending: { offsetMs, charStart },
    bound: false,
    timeTimer: setInterval(emitTime, TIME_INTERVAL_MS),
  };
  applyRate();
  ensureWindow();
  emitState('loading');
}

function ensureWindow() {
  if (!s) return;
  const last = Math.min(s.idx + WINDOW_AHEAD, s.chunks.length - 1);
  for (let i = s.idx; i <= last && s.inFlight < MAX_CONCURRENT; i++) {
    const entry = s.entries.get(i);
    if (entry && entry.status !== 'failed') continue;
    fetchChunk(i);
  }
}

function fetchChunk(idx) {
  const mySession = s;
  mySession.inFlight++;
  const entry = { status: 'fetching', abort: new AbortController() };
  mySession.entries.set(idx, entry);
  fetch(`${API}/api/tts`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ provider: mySession.provider, voice: mySession.voice, text: mySession.chunks[idx].text }),
    signal: entry.abort.signal,
  })
    .then(async (res) => {
      if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error ?? `TTS failed (${res.status})`);
      return res.json();
    })
    .then(({ audioBase64, words }) => {
      if (s !== mySession) return;
      const bytes = Uint8Array.from(atob(audioBase64), (c) => c.charCodeAt(0));
      entry.blobUrl = URL.createObjectURL(new Blob([bytes], { type: 'audio/mpeg' }));
      entry.words = words;
      entry.status = 'ready';
      onReady(idx, entry);
    })
    .catch((err) => {
      if (s !== mySession) return;
      entry.status = 'failed';
      if (idx === s.idx) {
        s.wantPlay = false;
        emitState('error', err.message);
      }
    })
    .finally(() => {
      if (s !== mySession) return;
      mySession.inFlight--;
      ensureWindow();
    });
}

function onReady(idx, entry) {
  if (!s) return;
  if (idx === s.idx && !s.bound) bind(entry);
  else if (idx === s.idx + 1) preload(idx, entry);
}

function bind(entry) {
  s.bound = true;
  const offset = resolveOffset(entry.words);
  s.pending = { offsetMs: 0, charStart: null };
  s.active.src = entry.blobUrl;
  applyRate();
  s.active.addEventListener(
    'loadedmetadata',
    () => {
      if (!s || !s.bound) return;
      if (offset > 0) s.active.currentTime = offset / 1000;
      if (s.wantPlay) s.active.play().catch((err) => emitState('error', `Playback failed: ${err.message}`));
    },
    { once: true },
  );
  s.active.load();
  send({ type: 'chunk-start', idx: s.idx, words: entry.words });
  emitState(s.wantPlay ? 'playing' : 'paused');
  maybePreloadNext();
}

function resolveOffset(words) {
  if (s.pending.charStart != null) {
    const w = words.find((w) => w.charStart >= 0 && w.charStart >= s.pending.charStart);
    return w ? w.startMs : 0;
  }
  return s.pending.offsetMs ?? 0;
}

function maybePreloadNext() {
  const next = s.idx + 1;
  if (next >= s.chunks.length || s.standbyIdx === next) return;
  const entry = s.entries.get(next);
  if (entry?.status === 'ready') preload(next, entry);
}

function preload(idx, entry) {
  s.standby.src = entry.blobUrl;
  applyRate(); // set defaultPlaybackRate before load() so the standby loads at the right rate
  s.standby.load();
  s.standbyIdx = idx;
}

function onEnded(el) {
  if (!s || el !== s.active) return;
  const next = s.idx + 1;
  if (next >= s.chunks.length) {
    s.wantPlay = false;
    emitState('ended');
    return;
  }
  const entry = s.entries.get(next);
  if (s.standbyIdx === next && entry?.status === 'ready') {
    [s.active, s.standby] = [s.standby, s.active];
    s.standbyIdx = -1;
    s.idx = next;
    applyRate();
    if (s.wantPlay) s.active.play().catch((err) => emitState('error', err.message));
    send({ type: 'chunk-start', idx: s.idx, words: entry.words });
    ensureWindow();
    maybePreloadNext();
  } else {
    goTo(next, { offsetMs: 0 });
  }
}

function goTo(idx, pending) {
  s.idx = Math.max(0, Math.min(idx, s.chunks.length - 1));
  s.bound = false;
  s.standbyIdx = -1;
  s.pending = { offsetMs: 0, charStart: null, ...pending };
  s.active.pause();
  ensureWindow();
  const entry = s.entries.get(s.idx);
  if (entry?.status === 'ready') bind(entry);
  else emitState('loading');
}

function applyRate() {
  if (!s) return;
  // defaultPlaybackRate must be set too: the media element load algorithm resets
  // playbackRate := defaultPlaybackRate on every resource load, so a rate set before
  // .load() (as in bind/preload) is otherwise erased back to 1×.
  for (const el of [s.active, s.standby]) {
    el.defaultPlaybackRate = s.rate;
    el.playbackRate = s.rate;
    el.preservesPitch = true;
  }
}

function emitTime() {
  if (!s || !s.bound) return;
  send({
    type: 'time',
    idx: s.idx,
    ms: s.active.currentTime * 1000,
    rate: s.rate,
    playing: s.wantPlay && !s.active.paused,
  });
}

function emitState(state, message) {
  send({ type: 'state', state, message, idx: s?.idx ?? 0, rate: s?.rate ?? 1 });
}

chrome.runtime.onMessage.addListener((msg, sender) => {
  // Only extension contexts (the service worker) speak this protocol; a
  // content script has sender.tab set and must never drive playback.
  if (sender?.tab !== undefined) return;
  if (!msg || msg.target !== 'offscreen') return;
  switch (msg.type) {
    case 'start':
      start(msg.payload);
      break;
    case 'toggle':
      if (!s) break;
      if (s.wantPlay) {
        s.wantPlay = false;
        s.active.pause();
        emitState('paused');
      } else {
        s.wantPlay = true;
        if (s.bound) s.active.play().catch((err) => emitState('error', err.message));
        else ensureWindow();
        emitState('playing');
      }
      break;
    case 'seek':
      if (s) {
        s.wantPlay = true;
        goTo(msg.chunkIdx, { charStart: msg.charStart ?? null, offsetMs: msg.offsetMs ?? 0 });
      }
      break;
    case 'rate':
      if (s) {
        s.rate = msg.value;
        applyRate();
        emitState(s.wantPlay ? 'playing' : 'paused');
      }
      break;
    case 'voice': {
      if (!s) break;
      const pos = { startChunk: s.idx, offsetMs: 0, provider: msg.provider, voice: msg.voice };
      start({ chunks: s.chunks, rate: s.rate, autoplay: s.wantPlay, ...pos });
      break;
    }
    case 'stop':
      stop();
      break;
  }
});

import { Router } from 'express';
import { getProvider } from '../providers/index.js';
import { cacheKey } from '../lib/cache.js';
import { createSemaphore, withTimeout, retryOnce } from '../lib/semaphore.js';

const MAX_TTS_CHARS = 2000;
// Fallbacks when a provider doesn't declare its own; the real values live in
// providers/index.js because they're provider-specific (network vs on-device).
const DEFAULT_TIMEOUT_MS = 20_000;
const DEFAULT_CONCURRENCY = 2;

export function ttsRouter({ cache }) {
  const router = Router();
  // One queue per provider, so a slow or stuck provider (on-device inference
  // runs for seconds) never holds the slots another provider needs.
  const queues = new Map();
  const queueFor = (name, provider) => {
    if (!queues.has(name)) {
      queues.set(name, createSemaphore(provider.concurrency ?? DEFAULT_CONCURRENCY));
    }
    return queues.get(name);
  };

  router.post('/', async (req, res, next) => {
    const { provider: providerName = 'edge', voice, text } = req.body ?? {};
    // A client that hangs up while its request waits for a slot (a seek, a
    // voice change, a closed tab) no longer wants that audio. Dropping it
    // hands the slot to the chunk the listener is actually waiting on.
    const abandoned = new AbortController();
    res.on('close', () => {
      if (!res.writableEnded) abandoned.abort();
    });
    try {
      if (!text || typeof text !== 'string' || !text.trim()) {
        return res.status(400).json({ error: 'text is required' });
      }
      if (text.length > MAX_TTS_CHARS) {
        return res.status(400).json({ error: `text exceeds ${MAX_TTS_CHARS} characters` });
      }
      if (!voice || typeof voice !== 'string') {
        return res.status(400).json({ error: 'voice is required' });
      }
      const provider = getProvider(providerName);
      if (!provider.available()) {
        return res
          .status(400)
          .json({ error: `Provider "${providerName}" is not configured (missing API key)` });
      }
      // Every provider builds a request from this id — SSML for edge, a file
      // path for supertonic — so it must be one the provider publishes, never
      // a caller-supplied string. Never echo the id back in the error.
      if (!(await provider.isKnownVoice(voice))) {
        return res.status(400).json({ error: `Unknown voice for provider "${providerName}"` });
      }

      const key = cacheKey(providerName, voice, text);
      const cached = await cache.get(key);
      if (cached) {
        return res.json({
          audioBase64: cached.audio.toString('base64'),
          format: cached.format,
          words: cached.words,
          cached: true,
        });
      }

      const timeoutMs = provider.timeoutMs ?? DEFAULT_TIMEOUT_MS;
      const retryOnTimeout = provider.retryOnTimeout ?? true;
      const result = await queueFor(providerName, provider).run(
        () =>
          retryOnce(
            () => withTimeout(provider.synthesize({ text, voice }), timeoutMs, 'TTS synthesis'),
            { shouldRetry: (err) => retryOnTimeout || !err.timeout },
          ),
        { signal: abandoned.signal },
      );
      res.json({
        audioBase64: result.audio.toString('base64'),
        format: result.format,
        words: result.words,
        cached: false,
      });
      // Persist after answering. The next queued synthesis starts the moment
      // this one frees its slot, and on-device inference blocks the event
      // loop in long steps, so every await ahead of the reply would wait
      // behind one of them. cache.get serves the entry until the files land.
      cache.put(key, result).catch((err) => {
        console.warn(`Lectern: could not cache TTS audio (${err.message})`);
      });
    } catch (err) {
      if (err.name === 'AbortError' && abandoned.signal.aborted) return; // nobody to answer
      err.status ??= 503;
      err.message = `TTS failed (${providerName}): ${err.message}`;
      next(err);
    }
  });

  return router;
}
import * as edge from './edge.js';
import * as elevenlabs from './elevenlabs.js';
import * as supertonic from './supertonic.js';
import * as kokoro from './kokoro.js';

// Each provider declares its own synthesis latency profile. Network providers
// (edge, elevenlabs) return in a few seconds or fail fast, so a tight timeout
// with retry-on-anything is right. Supertonic (ONNX diffusion) and Kokoro (ONNX
// StyleTTS 2) run on-device: CPU-bound and much slower, especially for long
// chunks, so they need a far larger ceiling; and because a timed-out inference
// is uncancelable and keeps using CPU, they must never be retried on timeout (a
// second attempt would race the abandoned first one and slow both down).
// `concurrency` is how many syntheses of one provider run at once; each
// provider gets its own queue. Network providers overlap well. onnxruntime-node
// runs each inference step synchronously and yields between steps, so two
// on-device requests interleave step by step and both finish late: one at a
// time delivers the chunk the listener is waiting on about twice as soon
// (3.6 s vs 7.4 s measured for Supertonic) for the same total throughput.
// `timeoutMs`/`retryOnTimeout`/`concurrency` are consumed by routes/tts.js.
export const providers = {
  edge: {
    synthesize: edge.synthesize,
    voices: edge.voices,
    isKnownVoice: edge.isKnownVoice,
    available: () => true,
    timeoutMs: 20_000,
    retryOnTimeout: true,
    concurrency: 2,
  },
  elevenlabs: {
    synthesize: elevenlabs.synthesize,
    voices: elevenlabs.voices,
    isKnownVoice: elevenlabs.isKnownVoice,
    available: elevenlabs.available,
    timeoutMs: 20_000,
    retryOnTimeout: true,
    concurrency: 2,
  },
  supertonic: {
    synthesize: supertonic.synthesize,
    voices: supertonic.voices,
    isKnownVoice: supertonic.isKnownVoice,
    available: supertonic.available,
    timeoutMs: 120_000,
    retryOnTimeout: false,
    concurrency: 1,
  },
  kokoro: {
    synthesize: kokoro.synthesize,
    voices: kokoro.voices,
    isKnownVoice: kokoro.isKnownVoice,
    available: kokoro.available,
    timeoutMs: 120_000,
    retryOnTimeout: false,
    concurrency: 1,
  },
};

export function getProvider(name) {
  // hasOwnProperty, not providers[name]: '__proto__', 'constructor' and
  // 'toString' are all truthy on a plain object and would sail past the guard
  // below, turning a bad request into a 5xx plus a stack trace in the log.
  const provider = Object.prototype.hasOwnProperty.call(providers, name) ? providers[name] : null;
  if (!provider) {
    throw Object.assign(new Error(`Unknown provider: ${name}`), { status: 400 });
  }
  return provider;
}
// The error a queued task settles with when its signal aborts before it gets
// a slot. Callers tell it apart by name (the Web platform's convention).
function abandonedError() {
  return Object.assign(new Error('Abandoned before a slot was free'), { name: 'AbortError' });
}

export function createSemaphore(max) {
  let active = 0;
  const waiters = [];

  const acquire = (signal) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) {
        reject(abandonedError());
        return;
      }
      if (active < max) {
        active++;
        resolve();
        return;
      }
      const waiter = { resolve, signal, onAbort: null };
      if (signal) {
        // leave the queue at once: an abandoned task must neither run nor
        // hold a place ahead of live ones
        waiter.onAbort = () => {
          const at = waiters.indexOf(waiter);
          if (at !== -1) waiters.splice(at, 1);
          reject(abandonedError());
        };
        signal.addEventListener('abort', waiter.onAbort, { once: true });
      }
      waiters.push(waiter);
    });

  const release = () => {
    const next = waiters.shift();
    if (next) {
      next.signal?.removeEventListener('abort', next.onAbort);
      next.resolve();
    } else {
      active--;
    }
  };

  return {
    // `signal` covers the wait for a slot only: once `fn` starts it runs to
    // completion, whatever the signal does afterwards.
    async run(fn, { signal } = {}) {
      await acquire(signal);
      try {
        return await fn();
      } finally {
        release();
      }
    },
  };
}

export function withTimeout(promise, ms, label = 'operation') {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(
      () => reject(Object.assign(new Error(`${label} timed out after ${ms}ms`), { timeout: true })),
      ms,
    );
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (err) => {
        clearTimeout(timer);
        reject(err);
      },
    );
  });
}

// Retry `fn` at most once. By default any failure is retried (transient network
// blips). Pass `shouldRetry` to opt out of retrying specific errors — e.g. an
// on-device synthesis timeout: the first attempt is uncancelable and keeps
// burning CPU, so a second concurrent attempt only compounds the load.
export async function retryOnce(fn, { shouldRetry = () => true } = {}) {
  try {
    return await fn();
  } catch (err) {
    if (!shouldRetry(err)) throw err;
    return await fn();
  }
}

// Lectern service worker — owns the (single) reading session, routes messages
// between the page engine (via bridge) and the offscreen audio document, and
// survives both its own idle termination and Chrome closing the offscreen doc
// after 30 s without audio (chrome.storage.session keeps the resume state).
const API = 'http://127.0.0.1:3000';
const DEFAULTS_KEY = 'lectern.defaults';

let session = null;
let sessionLoaded = false;
let lastPersist = 0;
// Tabs the user explicitly activated via a trusted entry point (toolbar click,
// context menu, keyboard command). Only these may start a reading session —
// see validUp() and the 'session-start' handler. An arm is spent by the
// session-start it authorizes, but not every gesture produces one (extraction
// can fail; a toolbar click can resolve to play/pause) — so arms also expire,
// rather than leaving a standing authorization the page could later spend on a
// forged session-start.
//
// The arm also carries a nonce, handed down to the document that received the
// gesture and echoed back in its session-start. A tab id alone is not an
// identity: within the 10 s TTL the tab can navigate, and the *next* document
// would otherwise inherit an unspent arm and start a session the user never
// authorized for it.
const ARM_TTL_MS = 10_000;
const armedTabs = new Map(); // tabId → { nonce, expiry }

function armTab(tabId) {
  const nonce = crypto.randomUUID();
  armedTabs.set(tabId, { nonce, expiry: Date.now() + ARM_TTL_MS });
  return nonce;
}

function consumeArm(tabId, nonce) {
  const arm = armedTabs.get(tabId);
  armedTabs.delete(tabId);
  return Boolean(arm) && arm.expiry > Date.now() && typeof nonce === 'string' && arm.nonce === nonce;
}

async function loadSession() {
  if (sessionLoaded) return;
  sessionLoaded = true;
  const stored = await chrome.storage.session.get('session');
  if (stored.session) session = stored.session;
}

function persistSession(force = false) {
  const now = Date.now();
  if (!force && now - lastPersist < 1000) return;
  lastPersist = now;
  if (session) chrome.storage.session.set({ session }).catch(() => {});
  else chrome.storage.session.remove('session').catch(() => {});
}

// The page picks a voice from the list we hand it, so the SW re-checks that a
// requested provider:voice is one the engine actually offers. Without this a
// page holding a session can rotate through arbitrary strings: every rotation
// misses the audio cache (the key includes the voice), re-synthesizes every
// chunk, and grows data/cache, which is never pruned by design. A bad string
// also persists as the global default and breaks every later read.
let voicesCache = null; // { at, payload, ids:Set<'provider:id'> }
const VOICES_TTL_MS = 5 * 60 * 1000;

async function fetchVoices() {
  if (voicesCache && Date.now() - voicesCache.at < VOICES_TTL_MS) return voicesCache;
  const payload = await fetch(`${API}/api/voices`).then((r) => (r.ok ? r.json() : null));
  if (!payload) return null;
  const ids = new Set();
  for (const [provider, group] of Object.entries(payload)) {
    for (const v of group?.voices ?? []) if (typeof v?.id === 'string') ids.add(`${provider}:${v.id}`);
  }
  voicesCache = { at: Date.now(), payload, ids };
  return voicesCache;
}

async function voiceAllowed(provider, voice) {
  try {
    const cached = await fetchVoices();
    return Boolean(cached?.ids.has(`${provider}:${voice}`));
  } catch {
    return false;
  }
}

async function defaults() {
  const stored = await chrome.storage.local.get(DEFAULTS_KEY);
  return { provider: 'edge', voice: 'en-US-AvaMultilingualNeural', rate: 1, ...(stored[DEFAULTS_KEY] ?? {}) };
}

function saveDefaults(patch) {
  defaults().then((d) => chrome.storage.local.set({ [DEFAULTS_KEY]: { ...d, ...patch } }));
}

/* ——— messaging helpers ——— */

// Pushes are addressed to the *document* that owns the session wherever we know
// it. A tab id alone would deliver the session's words to whatever document the
// tab holds now, which after a navigation is a page that never saw the content.
function sendDown(payload, tabId = session?.tabId, { broadcast = false } = {}) {
  if (tabId == null) return;
  // `broadcast` is for the gesture hand-off only: 'begin' has to reach the
  // document the tab holds *now*, which is exactly the one the user gestured on.
  const target =
    !broadcast && session?.tabId === tabId && session?.documentId
      ? { documentId: session.documentId }
      : undefined;
  const sent = target
    ? chrome.tabs.sendMessage(tabId, { __lecternDown: true, payload }, target)
    : chrome.tabs.sendMessage(tabId, { __lecternDown: true, payload });
  sent.catch(() => {
    // the tab navigated away or closed — the session is over
    if (session?.tabId === tabId) stopSession();
  });
}

function sendOffscreen(msg) {
  return chrome.runtime.sendMessage({ target: 'offscreen', ...msg }).catch(() => {});
}

async function hasOffscreen() {
  const contexts = await chrome.runtime.getContexts({ contextTypes: ['OFFSCREEN_DOCUMENT'] });
  return contexts.length > 0;
}

async function ensureOffscreen() {
  if (await hasOffscreen()) return;
  await chrome.offscreen.createDocument({
    url: 'offscreen.html',
    reasons: ['AUDIO_PLAYBACK'],
    justification: 'Plays text-to-speech narration for the current page',
  });
}

/* ——— session lifecycle ——— */

async function stopSession() {
  session = null;
  persistSession(true);
  if (await hasOffscreen()) await sendOffscreen({ type: 'stop' });
}

// Tabs opened before the extension loaded have no content scripts; the
// action/menu click grants activeTab, so inject them on demand.
async function ensureContentScripts(tabId) {
  try {
    await chrome.tabs.sendMessage(tabId, { __lecternPing: true });
    return true;
  } catch {
    try {
      await chrome.scripting.insertCSS({ target: { tabId }, files: ['content/lectern.css'] });
      await chrome.scripting.executeScript({ target: { tabId }, files: ['content/bridge.js'] });
      await chrome.scripting.executeScript({
        target: { tabId },
        world: 'MAIN',
        files: ['content/extract-core.js', 'content/engine.js'],
      });
      return true;
    } catch {
      return false; // chrome:// pages, the Web Store, PDFs, etc.
    }
  }
}

function flashBadge(tabId, text) {
  chrome.action.setBadgeText({ tabId, text }).catch(() => {});
  chrome.action.setBadgeBackgroundColor({ tabId, color: '#C8401F' }).catch(() => {});
  setTimeout(() => chrome.action.setBadgeText({ tabId, text: '' }).catch(() => {}), 3000);
}

async function beginSession(tabId, mode) {
  await loadSession();
  if (session && session.tabId !== tabId) {
    sendDown({ type: 'teardown' }, session.tabId);
    await stopSession();
  }
  if (!(await ensureContentScripts(tabId))) return false;
  // Arm the tab: the engine will reply with 'session-start', which is only
  // honored for an armed tab (a forged drive-by session-start is ignored).
  const nonce = armTab(tabId);
  // hasSession lets the page resolve an 'auto' click to play/pause only when
  // there is still a session here to control — otherwise it re-reads.
  sendDown({ type: 'begin', mode, hasSession: session?.tabId === tabId, nonce }, tabId, { broadcast: true });
  return true;
}

// Every user entry point routes through here: hand the gesture to the page,
// and when the page can't take content scripts (chrome://, the Web Store, the
// PDF viewer) fall back to controlling the session we still own for that tab,
// so a click is never silently a no-op.
async function activate(tabId, mode) {
  if (await beginSession(tabId, mode)) return;
  if (session?.tabId === tabId) await togglePlayback();
  else flashBadge(tabId, '✕');
}

async function onSessionStart(tabId, { blocks }, sender) {
  try {
    // Re-reading the same tab (the page grew, or the user selected a passage):
    // silence the old narration now rather than letting it run on until the
    // new audio binds.
    if (session?.tabId === tabId && (await hasOffscreen())) await sendOffscreen({ type: 'stop' });
    const res = await fetch(`${API}/api/segment`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ blocks }),
    });
    if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error ?? `Segmentation failed (${res.status})`);
    const { sentences, chunks } = await res.json();

    const prefs = await defaults();
    session = {
      tabId,
      // The document that received the user's gesture owns this session. Every
      // later control message must come from it, and every push goes to it.
      documentId: sender.documentId,
      // Title and URL come from the browser, never from the page's message: a
      // page that asserts its own provenance can plant a library entry titled
      // "Q3 Board Pack" sourced from a domain it does not own.
      ...(await provenance(tabId, sender)),
      blocks,
      chunkIdx: 0,
      inChunkMs: 0,
      ...prefs,
    };
    persistSession(true);

    let voices = null;
    try {
      voices = (await fetchVoices())?.payload ?? null;
    } catch {
      voices = null;
    }

    sendDown({
      type: 'segmented',
      sentences,
      chunks: chunks.map(({ text, ...meta }) => meta),
      voices,
      prefs,
    });

    await ensureOffscreen();
    await sendOffscreen({
      type: 'start',
      payload: {
        chunks: chunks.map((c) => ({ text: c.text })),
        startChunk: 0,
        provider: prefs.provider,
        voice: prefs.voice,
        rate: prefs.rate,
        autoplay: true,
      },
    });
  } catch (err) {
    sendDown(
      {
        type: 'error',
        message: `${err.message} — is the Lectern app running? (http://localhost:3000)`,
      },
      tabId,
    );
  }
}

async function provenance(tabId, sender) {
  const url = typeof sender?.url === 'string' ? sender.url.slice(0, 4000) : '';
  let title = '';
  try {
    title = (await chrome.tabs.get(tabId)).title ?? '';
  } catch {
    title = '';
  }
  if (!title) {
    try {
      title = new URL(url).hostname;
    } catch {
      title = 'Untitled page';
    }
  }
  return { title: title.slice(0, 2000), url };
}

// offscreen died (30 s paused) or SW restarted: rebuild playback at the saved position
async function rehydrateAndPlay() {
  if (!session) return;
  const res = await fetch(`${API}/api/segment`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ blocks: session.blocks }),
  });
  if (!res.ok) throw new Error('Lectern engine unreachable');
  const { chunks } = await res.json();
  await ensureOffscreen();
  await sendOffscreen({
    type: 'start',
    payload: {
      chunks: chunks.map((c) => ({ text: c.text })),
      startChunk: session.chunkIdx,
      offsetMs: session.inChunkMs,
      provider: session.provider,
      voice: session.voice,
      rate: session.rate,
      autoplay: true,
    },
  });
}

async function togglePlayback() {
  await loadSession();
  if (!session) return;
  if (await hasOffscreen()) {
    sendOffscreen({ type: 'toggle' });
  } else {
    try {
      await rehydrateAndPlay();
    } catch (err) {
      sendDown({ type: 'error', message: err.message });
    }
  }
}

/* ——— inbound message validation ——— */

// engine.js runs in the page's MAIN world, so any page can post a forged "up"
// envelope through the bridge. The SW therefore treats every inbound message as
// untrusted: validate type/shape/bounds and drop anything unexpected before
// acting on it. (Bounds mirror the server-side caps in lib/limits.js.)
const MAX_UP_BLOCKS = 5000;
const MAX_BLOCK_CHARS = 50_000; // mirrors server/lib/limits.js
const MAX_TOTAL_CHARS = 2_000_000; // mirrors server/lib/limits.js
const MAX_CHUNK_IDX = 100_000;

function isUpBlocks(v) {
  if (!Array.isArray(v) || v.length === 0 || v.length > MAX_UP_BLOCKS) return false;
  let total = 0;
  for (const b of v) {
    if (!b || typeof b.type !== 'string' || typeof b.text !== 'string') return false;
    if (b.text.length > MAX_BLOCK_CHARS) return false;
    total += b.text.length;
    if (total > MAX_TOTAL_CHARS) return false;
  }
  return true;
}

function validUp(msg) {
  if (!msg || typeof msg !== 'object' || typeof msg.type !== 'string') return false;
  switch (msg.type) {
    case 'session-start':
      // title/url are NOT taken from the page — see provenance().
      return isUpBlocks(msg.blocks) && typeof msg.nonce === 'string' && msg.nonce.length <= 64;
    case 'control':
      return typeof msg.action === 'string';
    case 'seek':
      return Number.isInteger(msg.chunkIdx) && msg.chunkIdx >= 0 && msg.chunkIdx <= MAX_CHUNK_IDX;
    case 'rate':
      return typeof msg.value === 'number' && msg.value > 0 && msg.value <= 4;
    case 'voice':
      return (
        typeof msg.provider === 'string' &&
        msg.provider.length <= 64 &&
        typeof msg.voice === 'string' &&
        msg.voice.length <= 256
      );
    case 'save-library':
    case 'session-end':
      return true;
    default:
      return false;
  }
}

/* ——— message routing ——— */

chrome.runtime.onMessage.addListener((msg, sender) => {
  if (msg?.__lecternUp && sender.tab?.id != null) {
    handleUp(sender.tab.id, msg.payload, sender);
    return;
  }
  if (msg?.target === 'sw') {
    handleOffscreen(msg, sender);
  }
});

// The session belongs to one document. A tab id is not an identity: the tab can
// navigate, and the next page would otherwise inherit the session — able to
// replay the previous page's words back to itself, save them to the library, or
// resume playback of content it never saw.
function ownsSession(tabId, sender) {
  return Boolean(session) && session.tabId === tabId && session.documentId === sender?.documentId;
}

async function handleUp(tabId, msg, sender) {
  if (!validUp(msg)) return;
  await loadSession();
  // One gate for every message that acts on a live session.
  if (msg.type !== 'session-start' && !ownsSession(tabId, sender)) return;
  switch (msg.type) {
    case 'session-start':
      // Only a document armed by a trusted user gesture may start a session; a
      // forged drive-by session-start is dropped here. Consume the arm so one
      // gesture authorizes exactly one session start, for exactly the document
      // that received the gesture.
      if (!consumeArm(tabId, msg.nonce)) break;
      await onSessionStart(tabId, msg, sender);
      break;
    case 'control':
      if (msg.action === 'toggle') await togglePlayback();
      break;
    case 'seek':
      if (!(await hasOffscreen())) {
        session.chunkIdx = msg.chunkIdx;
        session.inChunkMs = 0;
        persistSession(true);
        try {
          await rehydrateAndPlay();
        } catch (err) {
          sendDown({ type: 'error', message: err.message });
        }
        if (msg.charStart != null) sendOffscreen({ type: 'seek', chunkIdx: msg.chunkIdx, charStart: msg.charStart });
      } else {
        sendOffscreen({ type: 'seek', chunkIdx: msg.chunkIdx, charStart: msg.charStart ?? null });
      }
      break;
    case 'rate':
      saveDefaults({ rate: msg.value });
      session.rate = msg.value;
      persistSession(true);
      sendOffscreen({ type: 'rate', value: msg.value });
      break;
    case 'voice':
      // Only a provider:voice the engine actually offers, and at most one
      // switch a second: each switch re-synthesizes every chunk (the audio
      // cache is keyed by voice) and that cache is never pruned.
      if (!(await voiceAllowed(msg.provider, msg.voice))) break;
      if (Date.now() - (session.lastVoiceAt ?? 0) < 1000) break;
      session.lastVoiceAt = Date.now();
      saveDefaults({ provider: msg.provider, voice: msg.voice });
      session.provider = msg.provider;
      session.voice = msg.voice;
      persistSession(true);
      if (await hasOffscreen()) {
        sendOffscreen({ type: 'voice', provider: msg.provider, voice: msg.voice });
      }
      break;
    case 'save-library':
      // One save per session: the save button lives in the page's own world, so
      // a page holding a session could otherwise write the library full.
      if (session.saved) break;
      session.saved = true;
      try {
        const res = await fetch(`${API}/api/docs/import/blocks`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            title: session.title,
            source: { type: 'url', value: session.url },
            blocks: session.blocks,
          }),
        });
        if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error ?? 'Save failed');
        persistSession(true);
        sendDown({ type: 'saved' });
      } catch (err) {
        if (session) session.saved = false; // a failed save may be retried
        sendDown({ type: 'error', message: err.message });
      }
      break;
    case 'session-end':
      await stopSession();
      break;
  }
}

function handleOffscreen(msg, sender) {
  // Only our own offscreen document; nothing else in the extension speaks this
  // protocol, and a content script must never be able to.
  if (sender?.url !== chrome.runtime.getURL('offscreen.html')) return;
  if (!session) return;
  switch (msg.type) {
    case 'time':
      session.chunkIdx = msg.idx;
      session.inChunkMs = msg.ms;
      persistSession();
      sendDown({ type: 'time', idx: msg.idx, ms: msg.ms, rate: msg.rate, playing: msg.playing });
      break;
    case 'chunk-start':
      session.chunkIdx = msg.idx;
      session.inChunkMs = 0;
      persistSession();
      sendDown({ type: 'chunk', idx: msg.idx, words: msg.words });
      break;
    case 'state':
      sendDown({ type: 'state', state: msg.state, message: msg.message, rate: msg.rate });
      break;
  }
}

/* ——— user entry points ——— */

// The toolbar icon means "read this", not "play/pause": the page resolves an
// 'auto' click against its live DOM — a selection, content that arrived since
// we extracted (SPA answers, feed items), or nothing new, in which case the
// engine asks for a toggle itself.
chrome.action.onClicked.addListener(async (tab) => {
  if (tab.id == null) return;
  await activate(tab.id, 'auto');
});

chrome.runtime.onInstalled.addListener(() => {
  chrome.contextMenus.create({
    id: 'lectern-selection',
    title: 'Lectern: read selection',
    contexts: ['selection'],
  });
  chrome.contextMenus.create({
    id: 'lectern-from-here',
    title: 'Lectern: read from here',
    contexts: ['page', 'selection'],
  });
});

chrome.contextMenus.onClicked.addListener(async (info, tab) => {
  if (tab?.id == null) return;
  if (info.menuItemId === 'lectern-selection') await activate(tab.id, 'selection');
  if (info.menuItemId === 'lectern-from-here') await activate(tab.id, 'caret');
});

chrome.commands.onCommand.addListener(async (command) => {
  if (command === 'toggle-playback') await togglePlayback();
});

// A document load in the reading tab ends the session: the content is gone, and
// the incoming document must not inherit either the session or an unspent arm.
// (SPA route changes do not report 'loading', so in-page navigation survives.)
chrome.tabs.onUpdated.addListener(async (tabId, changeInfo) => {
  if (changeInfo.status !== 'loading') return;
  armedTabs.delete(tabId);
  await loadSession();
  if (session?.tabId === tabId) await stopSession();
});

chrome.tabs.onRemoved.addListener(async (tabId) => {
  armedTabs.delete(tabId);
  await loadSession();
  if (session?.tabId === tabId) await stopSession();
});

// e2e hooks: drive the same code paths as toolbar clicks / shortcuts.
// No lastFocusedWindow filter — headless CI windows often report no focus.
async function activeTabId() {
  const tabs = await chrome.tabs.query({ active: true });
  const tab = tabs.find((t) => t.url?.startsWith('http')) ?? tabs[0];
  return tab?.id ?? null;
}
globalThis.__lecternStart = async (mode = 'page', tabId = null) => {
  const target = tabId ?? (await activeTabId());
  if (target == null) throw new Error('lectern e2e hook: no active tab found');
  if (!(await beginSession(target, mode))) {
    throw new Error(`lectern e2e hook: content scripts not injectable into tab ${target}`);
  }
  return target;
};
globalThis.__lecternToggle = () => togglePlayback();
globalThis.__lecternState = async () => {
  await loadSession();
  return {
    session: session ? { ...session, blocks: session.blocks.length } : null,
    offscreen: await hasOffscreen(),
  };
};

// Lectern page engine (MAIN world — required for CSS.highlights to paint).
// Owns: DOM extraction (via __lecternCore), word/sentence karaoke highlights,
// auto-scroll, and the floating player UI. No page DOM is ever mutated for
// highlighting. Talks to the service worker through the isolated bridge with
// window.postMessage envelopes.
(() => {
  if (window.__lecternEngine) return;
  window.__lecternEngine = true;

  const core = globalThis.__lecternCore;
  if (!core) return;

  const up = (msg) => window.postMessage({ __lectern: 'up', msg }, '*');

  /* ——— caret capture for "read from here" ——— */

  let lastCaret = null;
  document.addEventListener(
    'contextmenu',
    (e) => {
      const range = document.caretRangeFromPoint?.(e.clientX, e.clientY);
      if (range) lastCaret = { node: range.startContainer, offset: range.startOffset };
    },
    { capture: true, passive: true },
  );

  /* ——— session state ——— */

  let live = null; // { blocks(with segments), bounded, sentences, chunks(meta), chunkWords: Map, sync, lastWord, lastSentence, raf }
  const wordHl = new Highlight();
  const sentHl = new Highlight();
  wordHl.priority = 2;
  sentHl.priority = 1;

  let ui = null;
  let barPos = null; // px position once dragged; survives close/reopen for the page's life
  let userScrolledAt = 0;
  let programmaticUntil = 0;
  const markScroll = () => {
    if (performance.now() > programmaticUntil) userScrolledAt = performance.now();
  };
  window.addEventListener('wheel', markScroll, { passive: true });
  window.addEventListener('touchmove', markScroll, { passive: true });

  /* ——— extraction ——— */

  function extract(mode, hasSession) {
    const pageBlocks = () => core.collectBlocks(core.pickRoot(document), window);
    if (mode === 'selection') {
      const blocks = core.blocksFromSelection(window.getSelection(), window);
      if (!blocks) return { error: 'Select some text first, then choose “read selection”.' };
      return { blocks, bounded: true };
    }
    if (mode === 'caret' && lastCaret) {
      const all = pageBlocks();
      const blocks = core.sliceFromCaret(all, lastCaret.node, lastCaret.offset) ?? all;
      return { blocks };
    }
    if (mode === 'auto') return resolveAuto(pageBlocks, hasSession);
    const blocks = pageBlocks();
    if (!blocks.length) return { error: 'No readable text found on this page.' };
    return { blocks };
  }

  // The toolbar click is a "read this" gesture, not a transport control, and
  // only the page can tell "pause" from "read what just appeared": it alone
  // sees the live DOM, the selection, and the blocks the session was built
  // from. Resolution order — a selection wins, then a page we aren't already
  // reading, then whatever the page grew since we extracted it (an SPA chat
  // answer, a new feed item), and only then play/pause.
  function resolveAuto(pageBlocks, hasSession) {
    const selected = core.blocksFromSelection(window.getSelection(), window);
    if (selected) return { blocks: selected, bounded: true };

    const all = pageBlocks();
    // No live session (first click, or the page reloaded under a session the
    // service worker still holds) → read the page. Same when the SW no longer
    // has the session: resolving to a toggle it would drop is a dead click.
    if (!live?.blocks?.length || !hasSession) {
      if (!all.length) return { error: 'No readable text found on this page.' };
      return { blocks: all };
    }
    // A selection-derived session is mid-page by definition, so "everything
    // after it" is the rest of the article, not newly arrived content.
    if (!live.bounded) {
      const grown = core.blocksAfter(live.blocks, all);
      if (grown === null) return all.length ? { blocks: all } : { toggle: true }; // page re-rendered
      if (grown.length) return { blocks: grown, grew: true };
    }
    return { toggle: true };
  }

  // `nonce` is the one-shot authorization the service worker minted for the
  // user's gesture on THIS document; it is the only thing that lets our
  // session-start through. Everything else in this file runs in the page's own
  // world and is therefore untrusted by design.
  function begin(mode, hasSession, nonce) {
    const { blocks, error, toggle, bounded, grew } = extract(mode, hasSession);
    if (toggle) {
      up({ type: 'control', action: 'toggle' }); // nothing new to read — transport control
      return;
    }
    teardown(false);
    if (error) {
      mountUi();
      setStatus('error', error);
      return;
    }
    live = {
      blocks,
      bounded: Boolean(bounded),
      sentences: null,
      chunks: null,
      chunkWords: new Map(),
      sync: null,
      lastWordIdx: -1,
      lastSentence: -1,
      raf: 0,
    };
    mountUi();
    setStatus('loading', grew ? 'Reading what’s new…' : 'Preparing…');
    // Title and URL are deliberately absent: the service worker takes them from
    // the browser, so a page cannot assert provenance for a library entry.
    up({
      type: 'session-start',
      nonce,
      blocks: blocks.map((b) => ({ type: b.type, text: b.text })),
    });
  }

  /* ——— highlights ——— */

  function registerHighlights() {
    CSS.highlights.set('lectern-word', wordHl);
    CSS.highlights.set('lectern-sentence', sentHl);
  }

  function clearHighlights() {
    wordHl.clear();
    sentHl.clear();
    CSS.highlights.delete('lectern-word');
    CSS.highlights.delete('lectern-sentence');
  }

  function buildChunkWords(idx, words) {
    if (!live?.chunks) return;
    const chunk = live.chunks[idx];
    const block = live.blocks[chunk.block];
    const built = words.map((w) => {
      if (w.charStart < 0) return { ...w, range: null, sentence: -1 };
      const start = chunk.start + w.charStart;
      const range = core.rangeFor(block, start, chunk.start + w.charEnd);
      let sentence = -1;
      for (let si = chunk.sentences[0]; si <= chunk.sentences[1]; si++) {
        const s = live.sentences[si];
        if (start >= s.start && start < s.end) {
          sentence = si;
          break;
        }
      }
      return { ...w, range, sentence };
    });
    let lastSeen = chunk.sentences[0];
    for (const w of built) {
      if (w.sentence === -1) w.sentence = lastSeen;
      else lastSeen = w.sentence;
    }
    live.chunkWords.set(idx, built);
    for (const old of live.chunkWords.keys()) {
      if (Math.abs(old - idx) > 2) live.chunkWords.delete(old);
    }
  }

  function sentenceRange(si) {
    const s = live.sentences[si];
    return core.rangeFor(live.blocks[s.block], s.start, s.end);
  }

  function tick() {
    live.raf = requestAnimationFrame(tick);
    const sync = live?.sync;
    if (!sync) return;
    const words = live.chunkWords.get(sync.idx);
    if (!words?.length) return;
    const t = sync.ms + (sync.playing ? (performance.now() - sync.recvAt) * sync.rate : 0);

    let lo = 0;
    let hi = words.length - 1;
    let wi = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (words[mid].startMs <= t) {
        wi = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    if (wi === live.lastWordIdx || wi < 0) return;
    live.lastWordIdx = wi;

    const word = words[wi];
    wordHl.clear();
    if (word.range && word.range.startContainer.isConnected) wordHl.add(word.range);

    if (word.sentence !== live.lastSentence && word.sentence >= 0) {
      live.lastSentence = word.sentence;
      const range = sentenceRange(word.sentence);
      sentHl.clear();
      if (range) {
        sentHl.add(range);
        if (performance.now() - userScrolledAt > 3000) {
          programmaticUntil = performance.now() + 1000;
          (range.startContainer.parentElement ?? range.startContainer).scrollIntoView?.({
            behavior: 'smooth',
            block: 'center',
          });
        }
      }
    }
  }

  /* ——— sentence skip / seek / click-to-jump ——— */

  function jumpToSentence(si) {
    if (!live?.chunks) return;
    const chunkIdx = live.chunks.findIndex((c) => si >= c.sentences[0] && si <= c.sentences[1]);
    if (chunkIdx === -1) return;
    const charStart = Math.max(0, live.sentences[si].start - live.chunks[chunkIdx].start);
    live.lastWordIdx = -1;
    live.lastSentence = si;
    const range = sentenceRange(si);
    wordHl.clear();
    sentHl.clear();
    if (range) sentHl.add(range);
    up({ type: 'seek', chunkIdx, charStart });
  }

  function skipSentence(dir) {
    if (!live?.sentences) return;
    const from = live.lastSentence >= 0 ? live.lastSentence : 0;
    jumpToSentence(Math.max(0, Math.min(from + dir, live.sentences.length - 1)));
  }

  function sentenceAtOffset(blockIdx, offset) {
    let fallback = -1;
    for (let si = 0; si < live.sentences.length; si++) {
      const s = live.sentences[si];
      if (s.block !== blockIdx) continue;
      if (fallback === -1) fallback = si;
      if (offset >= s.start && offset < s.end) return si;
      if (offset < s.start) return si; // clicked the gap before this sentence
    }
    return fallback;
  }

  const INTERACTIVE =
    'a, button, input, select, textarea, summary, label, [contenteditable], ' +
    '[role="button"], [role="link"], [role="tab"], [role="menuitem"], [role="checkbox"]';

  // Speechify-style click-to-jump: while a session is active, clicking read
  // text seeks the audio there. Capture phase so SPA handlers that stop
  // propagation can't hide clicks from us; we never preventDefault, so the
  // page's own behavior is untouched.
  document.addEventListener(
    'click',
    (e) => {
      if (!live?.chunks || !live.sentences) return;
      if (ui && ui.host.contains(e.target)) return;
      if (e.target.closest?.(INTERACTIVE)) return;
      const sel = window.getSelection();
      if (sel && !sel.isCollapsed) return; // they're selecting, not jumping
      const range = document.caretRangeFromPoint?.(e.clientX, e.clientY);
      if (!range) return;
      const loc = core.locate(live.blocks, range.startContainer, range.startOffset);
      if (!loc) return;
      const si = sentenceAtOffset(loc.blockIdx, loc.normOffset);
      if (si >= 0) jumpToSentence(si);
    },
    true,
  );

  /* ——— floating UI (shadow DOM) ——— */

  // Material 3 Expressive floating toolbar, mirrored from public/style.css:
  // the play control is a circle at rest and a rounded square while reading,
  // a tonal square holding a morphing shape while audio synthesizes; the
  // status is a chip whose tone follows the state; spatial transitions use
  // spring easings, color transitions never overshoot.
  const UI_CSS = `
    :host { all: initial; position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%);
            z-index: 2147483647; font-family: -apple-system, 'Helvetica Neue', sans-serif;
            --spring: linear(0, 0.3 6%, 0.66 13%, 0.93 21%, 1.07 30%, 1.09 38%, 1.04 48%, 0.99 60%, 0.985 72%, 1);
            --spring-fast: linear(0, 0.42 6.6%, 0.78 13.5%, 1.02 21%, 1.11 28.5%, 1.08 36%, 1.01 46%, 0.98 56%, 0.99 68%, 1);
            --ease: cubic-bezier(0.2, 0, 0, 1); }
    .bar { display: flex; align-items: center; gap: 8px; background: #211d16; color: #f4eee1;
           border-radius: 28px; padding: 8px 12px 8px 8px; box-shadow: 0 18px 50px -12px rgba(0,0,0,.55);
           min-width: 400px; cursor: grab; user-select: none; -webkit-user-select: none;
           touch-action: none; animation: in .5s var(--spring) both; }
    .bar.dragging { cursor: grabbing; }
