  if (!styleCache.has(id)) {
    if (!existsSync(voiceStylePath(id))) {
      throw Object.assign(new Error('Unknown Supertonic voice'), { status: 400 });
    }
    const h = await helper();
    styleCache.set(id, h.loadVoiceStyle([voiceStylePath(id)]));
