// Measure playback stalls in the real extension: headless Chrome, unpacked
// extension, a long page whose text is unique per run (no cache hits), the given
// provider/voice/rate. Prints stall count and durations after the first audio.
// usage: node stalls.mjs <provider> <voice> <rate> <seconds>
import { createServer } from 'node:http';
import { createRequire } from 'node:module';
import path from 'node:path';

const root = '/Users/hungpq2412/lectern';
const req = createRequire(path.join(root, 'package.json'));
const puppeteer = (await import(req.resolve('puppeteer-core'))).default;
const [provider = 'supertonic', voice = 'M1', rateArg = '2', secondsArg = '120'] = process.argv.slice(2);
const rate = Number(rateArg);
const seconds = Number(secondsArg);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const corpus = [
  'Audiobooks were once a niche product, sold on cassette tapes to long-haul commuters.',
  'Today, listening is one of the fastest growing ways people consume the written word.',
  'Comprehension studies comparing listening and reading have found broadly similar outcomes for narrative text.',
  'The picture changes for dense technical material, where readers retain more when they can glance back.',
  'Listening frees the eyes but taxes working memory, and the best systems let you do both at once.',
  'Synchronized highlighting improves recall for most readers, especially on unfamiliar topics.',
  'Tools that pair text with audio have existed in assistive technology for decades.',
  'What changed is voice quality, because modern neural voices removed the robotic edge that drove people away.',
  'A reader who can follow along at twice the speed covers a long report during a short train ride.',
  'The hard part is not the voice itself but keeping the words and the sound perfectly in step.',
  'Every sentence has to arrive before the previous one ends, or the listener hears an awkward silence.',
  'Engineers measure this with the real time factor, which compares synthesis time with audio length.',
];
const nonce = Math.random().toString(36).slice(2, 7);
const words = ['amber', 'birch', 'cedar', 'delta', 'ember', 'fjord', 'grove', 'harbor', 'iris', 'juniper'];
const paragraphs = [];
for (let p = 0; p < 40; p++) {
  const sentences = [];
  for (let s = 0; s < 3; s++) {
    const base = corpus[(p * 3 + s) % corpus.length];
    sentences.push(`${base.slice(0, -1)}, noted ${words[p % 10]} ${words[(p + s + 3) % 10]} ${nonce}${p}${s}.`);
  }
  paragraphs.push(`<p>${sentences.join(' ')}</p>`);
}
const html = `<!doctype html><html><head><meta charset="utf-8"><title>Stall probe</title></head><body><main><article><h1>Stall probe ${nonce}</h1>${paragraphs.join('\n')}</article></main></body></html>`;
const server = createServer((_q, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html' });
  res.end(html);
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const url = `http://127.0.0.1:${server.address().port}/`;

const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: 'new',
  pipe: true,
  enableExtensions: [path.join(root, 'extension')],
  args: ['--autoplay-policy=no-user-gesture-required', '--mute-audio', '--window-size=1300,900'],
});
try {
  const swTarget = await browser.waitForTarget((t) => t.type() === 'service_worker' && t.url().endsWith('sw.js'), { timeout: 10_000 });
  const sw = await swTarget.worker();
  await sw.evaluate((d) => chrome.storage.local.set({ 'lectern.defaults': d }), { provider, voice, rate });
  const page = await browser.newPage();
  await page.goto(url, { waitUntil: 'load' });
  await sleep(500);
  const startedAt = Date.now();
  await sw.evaluate(() => globalThis.__lecternStart('page'));
  await page.waitForFunction(() => Boolean(document.querySelector('[data-lectern]')?.shadowRoot?.querySelector('.bar')), { timeout: 15_000 });
  await page.evaluate(() => {
    const bar = document.querySelector('[data-lectern]').shadowRoot.querySelector('.bar');
    const log = [];
    let last = null;
    const sample = () => {
      const state = bar.classList.contains('playing') ? 'playing' : bar.classList.contains('loading') ? 'loading' : 'other';
      if (state !== last) {
        log.push({ t: performance.now(), state });
        last = state;
      }
    };
    new MutationObserver(sample).observe(bar, { attributes: true, attributeFilter: ['class'] });
    setInterval(sample, 50);
    sample();
    window.__probe = log;
  });
  await page.waitForFunction(() => window.__probe.some((x) => x.state === 'playing'), { timeout: 120_000 });
  const firstAudioMs = Date.now() - startedAt;
  await sleep(seconds * 1000);
  const log = await page.evaluate(() => [...window.__probe, { t: performance.now(), state: 'end' }]);
  const { session } = await sw.evaluate(() => globalThis.__lecternState());
  const first = log.findIndex((x) => x.state === 'playing');
  const stalls = [];
  let playingMs = 0;
  for (let i = first; i < log.length - 1; i++) {
    const dur = log[i + 1].t - log[i].t;
    if (log[i].state === 'loading') stalls.push(Math.round(dur));
    if (log[i].state === 'playing') playingMs += dur;
  }
  console.log(
    JSON.stringify({
      provider, voice, rate, seconds, firstAudioMs,
      stalls: stalls.length,
      stallMsTotal: stalls.reduce((a, b) => a + b, 0),
      stallMsMax: Math.max(0, ...stalls),
      playingMs: Math.round(playingMs),
      chunkIdx: session?.chunkIdx,
      stallList: stalls,
    }),
  );
} finally {
  await browser.close();
  server.close();
}

